// zbr:selfhost/TypeChecker.zbr:5011
    var mixin_names = std.ArrayList([]const u8).empty;
// zbr:selfhost/TypeChecker.zbr:5012
    for (m.decls.items) |d0| {
// zbr:selfhost/TypeChecker.zbr:5013
        if (d0 == .interface_) {
